select null, t.id, 'builtin', 'An infant has a positive Clinitest (reducing substances) but a negative reagent strip glucose. This suggests:', '["Diabetes mellitus","Renal glycosuria","Galactosemia","Phenylketonuria"]'::jsonb, 2, 'Clinitest reacts with reducing sugars such as galactose, while the glucose oxidase strip reacts only with glucose. A positive Clinitest in this setting suggests galactosemia. Reference: A case of galactosemia misdiagnosed as cow''s milk intolerance (pmc.ncbi.nlm.nih.gov/articles/PMC3462687); Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984).', 1, 'verified'
