select null, t.id, 'builtin', 'A positive urine nitrite test means bacteria in the urine can:', '["Reduce nitrate to nitrite","Oxidize nitrite to nitrate","Produce leukocyte esterase","Hydrolyze urea"]'::jsonb, 0, 'Nitrite is not normally in urine; it appears when bacteria reduce urinary nitrate to nitrite. A short bladder incubation time can give false-negative results. Reference: Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html); Delanghe & Speeckaert, Preanalytical requirements of urinalysis, Biochem Med 2014 (pmc.ncbi.nlm.nih.gov/articles/PMC3936984).', 1, 'verified'
