  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('High urine ascorbic acid can cause false-negative reagent strip results for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Hyaline casts are made mainly of:', '["Albumin","Uromodulin (Tamm-Horsfall protein)","Fibrin","Immunoglobulin light chains"]'::jsonb, 1, 'Hyaline casts are a colorless fibrillary matrix of Tamm-Horsfall protein (uromodulin), the protein that forms the base of all casts. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', 1, 'verified'
