insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which cast, highly refractile with cracked or notched edges, is seen in advanced renal failure?', '["Hyaline","Granular","Waxy","Fatty"]'::jsonb, 2, 'Waxy casts are seen in renal failure (acute and chronic) and are linked to advanced renal disease. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840); Simerville et al., Urinalysis: A Comprehensive Review, AFP 2005 (aafp.org/pubs/afp/issues/2005/0315/p1153.html).', 2, 'verified'
