insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Calcium oxalate crystals in the urine of a patient with a high anion gap may suggest poisoning with:', '["Methanol","Ethylene glycol","Acetaminophen","Lead"]'::jsonb, 1, 'Ethylene glycol (antifreeze) is metabolized to oxalate, which forms calcium oxalate crystals in urine. Methanol also causes a high anion gap but does not form oxalate. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840).', 2, 'verified'
