insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Squamous epithelial cells covered with coccobacilli (clue cells) indicate:', '["Trichomoniasis","Candidiasis","Bacterial vaginosis (Gardnerella vaginalis)","Gonorrhea"]'::jsonb, 2, 'Clue cells (vaginal epithelial cells studded with adherent bacteria) are one of the Amsel criteria for bacterial vaginosis. Reference: CDC STI Treatment Guidelines, Bacterial Vaginosis (cdc.gov/std/treatment-guidelines/bv.htm).', 1, 'verified'
