insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which crystal is found in ACIDIC urine?', '["Triple phosphate","Amorphous phosphates","Uric acid","Calcium carbonate"]'::jsonb, 2, 'Uric acid crystals form in acidic urine (pH 5.8 or lower). Triple phosphate crystals form in alkaline urine (pH 7.0 or higher). Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840).', 1, 'verified'
