insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Wright or Hansel stain has traditionally been used to detect which urinary cells?', '["Eosinophils","Lymphocytes","Yeast","Renal tubular cells"]'::jsonb, 0, 'Urine eosinophils were once used to support acute interstitial nephritis, but eosinophiluria is no longer considered sensitive or specific for AIN, and the stain is no longer recommended. Reference: Gaggar & Raju, Diagnostic Utility of Urine Microscopy in Kidney Diseases, Indian J Nephrol 2024 (pmc.ncbi.nlm.nih.gov/articles/PMC11303840).', 2, 'verified'
