insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A CSF-to-serum glucose ratio below about 0.4 most strongly suggests:', '["Viral meningitis","Bacterial meningitis","Multiple sclerosis","Normal CSF"]'::jsonb, 1, 'The normal CSF-to-serum glucose ratio is about 0.6. Ratios below 0.4 are very indicative of a bacterial cause of low CSF glucose. Reference: CSF in acute and chronic infectious diseases (pmc.ncbi.nlm.nih.gov/articles/PMC7150022).', 1, 'verified'
