insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which CSF pattern is typical of bacterial meningitis?', '["Lymphocytes, normal glucose, mildly raised protein","Neutrophils, low glucose, markedly raised protein","Monocytes, normal glucose, normal protein","Lymphocytes, low glucose, normal lactate"]'::jsonb, 1, 'Bacterial meningitis classically has a very high, mainly neutrophilic pleocytosis, low glucose and high protein. Not every patient shows the classic pattern. Reference: Mount & Boyle, Aseptic and Bacterial Meningitis, AFP 2017 (aafp.org/pubs/afp/issues/2017/0901/p314.html).', 2, 'verified'
