insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Oligoclonal bands seen in CSF but NOT in the serum suggest:', '["Reye syndrome","Hepatic encephalopathy","Multiple sclerosis","Bacterial meningitis"]'::jsonb, 2, 'Bands found only in CSF show IgG made inside the CNS and are the most important laboratory evidence of multiple sclerosis. They are not fully specific: infections and other CNS autoimmune diseases can also cause them. Reference: The Persisting Significance of Oligoclonal Bands in the Diagnosis of Multiple Sclerosis (pmc.ncbi.nlm.nih.gov/articles/PMC6320811).', 2, 'verified'
