insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'In pleural fluid, a fluid-to-serum total protein ratio greater than 0.5 indicates:', '["A transudate","An exudate","A chylous effusion","Normal fluid"]'::jsonb, 1, 'By Light''s criteria, a fluid is an exudate if protein ratio >0.5, LD ratio >0.6, or fluid LD is above two-thirds of the serum upper limit. Reference: Biochemical Analysis of Pleural Fluid and Ascites (pmc.ncbi.nlm.nih.gov/articles/PMC6223608).', 2, 'verified'
