insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Rhomboid, weakly positively birefringent crystals in synovial fluid are:', '["Monosodium urate","Calcium pyrophosphate dihydrate","Cholesterol","Corticosteroid"]'::jsonb, 1, 'CPPD crystals are rod-like or rhomboid with weak birefringence (pseudogout). Monosodium urate crystals are fine needles with strong negative birefringence (gout). Reference: Croatian national recommendations for extravascular body fluids, Part II, Biochem Med 2020 (pmc.ncbi.nlm.nih.gov/articles/PMC7394252).', 2, 'verified'
