select null, t.id, 'builtin', 'An amniotic fluid lecithin/sphingomyelin (L/S) ratio indicating fetal lung maturity is:', '["0.5","1.0","1.5","Greater than 2.0"]'::jsonb, 3, 'An L/S ratio above 2.0 has been the accepted cutoff for fetal lung maturity in nondiabetic pregnancies. Reference: Revisiting Amniocentesis for Fetal Lung Maturity After 36 Weeks'' Gestation (pmc.ncbi.nlm.nih.gov/articles/PMC2505159).', 2, 'verified'
