insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Which stain is used for the qualitative fecal fat screen?', '["Wright stain","Gram stain","Sudan III","Methylene blue"]'::jsonb, 2, 'Qualitative fat stains such as Sudan III are used as a screening tool for steatorrhea. Methylene blue is used for fecal leukocytes. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', 1, 'verified'
