insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Fecal leukocytes seen with methylene blue are typically present in diarrhea caused by:', '["Rotavirus","Shigella","Vibrio cholerae","Staphylococcus aureus food poisoning"]'::jsonb, 1, 'Fecal leukocytes point to inflammatory diarrhea from invasive bacteria such as Shigella. They are not seen in viral diarrhea. Microscopy misses 30 to 40% of cases. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453); Turgeon & Fritsche, Laboratory approaches to infectious diarrhea (pmc.ncbi.nlm.nih.gov/articles/PMC7135126).', 2, 'verified'
