insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Pale, clay-colored stools suggest:', '["Bile duct obstruction","Upper GI bleeding","Iron therapy","High intake of green vegetables"]'::jsonb, 0, 'Clay- or putty-colored stool is seen in biliary obstruction, because bile pigments do not reach the intestine. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', 1, 'verified'
