insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Black, tarry stools (melena) suggest bleeding from the:', '["Rectum","Lower colon","Upper gastrointestinal tract","Anal canal"]'::jsonb, 2, 'When more than about 100 mL of blood is lost from the upper GI tract, the stool becomes black and tarry. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', 1, 'verified'
