insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'Quantitative fecal fat testing uses a stool collection of:', '["A random sample","24 hours","72 hours","7 days"]'::jsonb, 2, 'Stool is collected for 72 hours while the patient eats a diet with 100 g of fat daily. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', 2, 'verified'
