insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'The Apt test on a newborn''s bloody stool is used to tell:', '["Whether the blood is the baby''s own or swallowed maternal blood","The baby''s ABO group","Whether bleeding is from the upper or lower GI tract","How much blood was lost"]'::jsonb, 0, 'The Apt test distinguishes fetal from adult hemoglobin, so it shows whether blood in a newborn''s stool is the baby''s own or swallowed maternal blood. Reference: Approach to the bleeding newborn (pmc.ncbi.nlm.nih.gov/articles/PMC2851303).', 2, 'verified'
