insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, difficulty, status)
select null, t.id, 'builtin', 'A stool pH below 5.5 with a positive test for reducing substances suggests:', '["Carbohydrate malabsorption or intolerance","Pancreatic fat malabsorption","Upper GI bleeding","Bile duct obstruction"]'::jsonb, 0, 'A fecal pH below 5.5 means acidic stool, and reducing substances are tested when carbohydrate malabsorption is suspected, because unabsorbed sugars are fermented into acids. Reference: Kasirga, The importance of stool tests in diagnosis and follow-up of gastrointestinal disorders in children, Turk Pediatri Ars 2019 (pmc.ncbi.nlm.nih.gov/articles/PMC6776453).', 3, 'verified'
